SELECT id, name, description, price, placement, stock,
categoryLevel1Id, categoryLevel2Id, categoryLevel3Id,
fileName, isDelete, createdBy, creationDate, modifyBy, modifyDate,
approvalStatus
FROM tb_product

    isDelete = 0

        AND name LIKE CONCAT('%', #{name}, '%')


        AND categoryLevel1Id = #{categoryLevel1Id}


        AND categoryLevel2Id = #{categoryLevel2Id}


        AND createdBy = #{createdBy}


ORDER BY creationDate DESC
LIMIT #{start}, #{size}

